    method: "POST",
    headers: { "Content-Type": "text/plain" },
    body: c4,
  });
  out.status = res.status;
  const text = await res.text();
  out.len = text.length;
  out.head = text.slice(0, 400);
  out.isSvg = text.trim().startsWith("<svg") || text.includes("<svg");
} catch (e) {
  out.error = String(e);
}
return out;

